def solution(land):
    if not land:
        return 0
    
    # dp[j] = j번 열에서 현재 행을 밟았을 때 누적 최대 점수
    dp = land[0][:]  # 첫 행 초기화
    
    for i in range(1, len(land)):
        new_dp = [0] * 4
        for j in range(4):  # 현재 행에서 선택할 열
            # 직전 행에서 j가 아닌 열 중 최대값
            new_dp[j] = max(dp[k] for k in range(4) if k != j) + land[i][j]
        dp = new_dp
    
    return max(dp)

